previewCss:
.darma-loader-darma-b13-turnstile-gate { --accent: var(--loader-color, #0ea5e9); --accent-2: var(--loader-secondary-color, #475569); width: var(--loader-size, 100px); height: var(--loader-size, 100px); position: relative; display: grid; place-items: center; border-radius: 50%; background: color-mix(in srgb, #fff 66%, var(--accent-2)); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 14%, var(--accent-2)); }
.darma-loader-darma-b13-turnstile-gate::after { content: ''; position: absolute; width: 22%; height: 22%; border-radius: 50%; background: radial-gradient(circle at 38% 32%, color-mix(in srgb, #fff 30%, var(--accent-2)), color-mix(in srgb, #000 30%, var(--accent-2))); }
.darma-loader-darma-b13-turnstile-gate .darma-loader-darma-b13-turnstile-gate__arms { position: relative; width: 100%; height: 100%; animation: darma-loader-darma-b13-turnstile-gate-ratchet calc(var(--loader-speed, 1s) * 2.7) cubic-bezier(.5, 0, .18, 1) infinite; }
.darma-loader-darma-b13-turnstile-gate .darma-loader-darma-b13-turnstile-gate__arms span { position: absolute; top: 50%; left: 50%; width: 46%; height: 7%; margin-top: -3.5%; border-radius: 999px; transform-origin: left center; background: linear-gradient(90deg, var(--accent), color-mix(in srgb, #000 20%, var(--accent))); }
.darma-loader-darma-b13-turnstile-gate .darma-loader-darma-b13-turnstile-gate__arms span:nth-child(2) { transform: rotate(120deg); }
.darma-loader-darma-b13-turnstile-gate .darma-loader-darma-b13-turnstile-gate__arms span:nth-child(3) { transform: rotate(240deg); }
@keyframes darma-loader-darma-b13-turnstile-gate-ratchet { 0%, 16% { transform: rotate(0deg); } 33%, 49% { transform: rotate(120deg); } 66%, 82% { transform: rotate(240deg); } 100% { transform: rotate(360deg); } }

